CITE = re.compile(r"\s*\{\{[a-z0-9-]+\}\}")
CITEK = re.compile(r"\{\{([a-z0-9-]+)\}\}")
for _m in M:
    for _b in _m["blocks"]:
        if _b.get("t") == "table":
            keys = []
            def clean(x):
                for k in CITEK.findall(x):
                    if k not in keys:
                        keys.append(k)
                return CITE.sub("", x).strip()
            _b["title"] = clean(_b["title"]); _b["head"] = [clean(c) for c in _b["head"]]; _b["rows"] = [[clean(c) for c in r] for r in _b["rows"]]
            have = set(CITEK.findall(_b.get("src", "")))
            extra = " ".join("{{%s}}" % k for k in keys if k not in have)
            _b["src"] = (_b.get("src", "") + " " + extra).strip()

out = {"refs": refs, "modules": M}
Path(__file__).with_suffix(".json").write_text(json.dumps(out, ensure_ascii=False, indent=1), encoding="utf-8")
print(len(M), "modules")
